import type {Page,Locator} from '@playwright/test';
async function inEditorSection(page:Page,locator:Locator){if(!await locator.count())await locator.first().waitFor({state:"attached",timeout:1500}).catch(()=>{});if(await locator.count()){const section=await locator.first().evaluate(el=>el.closest('[data-editor-section]')?.getAttribute('data-editor-section'));if(section){if(section==='step'){const current=page.locator('.step-nav.active .step-select');await (await current.count()?current:page.locator('.step-select').first()).click()}else{await page.getByRole('button',{name:({header:'Hlavička',footer:'Päta',bottom:'Spodné časti strán'} as Record<string,string>)[section],exact:true}).click()}}}return locator}
import {readFileSync} from 'node:fs';
import {unzipSync,zipSync,strFromU8,strToU8} from 'fflate';
import { test, expect } from '@playwright/test';
const image = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="600" height="400"><rect width="600" height="400" fill="#dce8e3"/><circle cx="300" cy="200" r="130" fill="#335d4b"/><circle cx="300" cy="200" r="70" fill="#9fbca8"/><text x="300" y="365" text-anchor="middle" font-size="24">KONTROLA DIELU</text></svg>');
test('kompletná návodka: fotografie, anotácie, presuny, uloženie, export, import, tlač', async ({ page }) => {
    const errors: string[] = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto('/');
    await (await inEditorSection(page, page.getByRole('button', { name: 'Nová návodka', exact: false }))).click();
    await (await inEditorSection(page, page.getByLabel('Číslo produktu / Product number'))).fill('DH110-750');
    await (await inEditorSection(page, page.getByLabel('Proces / Process'))).fill('Výstupná kontrola');
    await (await inEditorSection(page, page.getByLabel('Vypracoval / Prepared by'))).fill('Sabína');
    await (await inEditorSection(page, page.getByLabel('Názov kroku', { exact: true }))).fill('Kontrola obvodu');
    await (await inEditorSection(page, page.getByLabel('Popis postupu / kontrolné kritériá'))).fill('Skontrolovať obvod dielu na nedoliatky a prestreky.');
    await (await inEditorSection(page, page.getByLabel('CT (sekundy)'))).fill('30');
    await (await inEditorSection(page, page.getByLabel('Výsledok', { exact: true }))).selectOption('OK');
    // Vytvorenie skutočného PNG z ilustrácie v prehliadači.
    const png = await page.evaluate(async (svg) => { const i = new Image(); i.src = 'data:image/svg+xml;base64,' + btoa(svg); await i.decode(); const c = document.createElement('canvas'); c.width = 600; c.height = 400; c.getContext('2d')!.drawImage(i, 0, 0); return c.toDataURL('image/png').split(',')[1]; }, image.toString());
    await (await inEditorSection(page, page.getByLabel('Pridať fotografie OK',{exact:true}))).setInputFiles([{ name: 'diel-ok.png', mimeType: 'image/png', buffer: Buffer.from(png, 'base64') }, { name: 'diel-nok.png', mimeType: 'image/png', buffer: Buffer.from(png, 'base64') }]);
    await expect((await inEditorSection(page, page.locator('.photo-card')))).toHaveCount(2);
    await (await inEditorSection(page, page.getByLabel('Zaradenie diel-ok.png'))).selectOption('OK');
    await (await inEditorSection(page, page.getByLabel('Zaradenie diel-nok.png'))).selectOption('NOK');
    const svg = (await inEditorSection(page, page.locator('.photo-card svg'))).first();
    await svg.evaluate(el=>el.scrollIntoView({block:'center'}));
    let r = (await svg.boundingBox())!;
    for (const label of ['◯ Kruh', '↗ Šípka', '▭ Obdĺžnik']) {
        await (await inEditorSection(page, page.getByRole('button', { name: label, exact: true }))).click();
        await svg.evaluate(el=>el.scrollIntoView({block:'center'}));r=(await svg.boundingBox())!;
        await page.mouse.move(r.x + r.width * .2, r.y + r.height * .2);
        await page.mouse.down();
        await page.mouse.move(r.x + r.width * .7, r.y + r.height * .7);
        await page.mouse.up();
    }
    await (await inEditorSection(page, page.getByRole('button', { name: '① Číslo', exact: true }))).click();
    await svg.click({ position: { x: r.width * .4, y: r.height * .4 } });
    await expect(svg.locator('[data-mark-id]')).toHaveCount(4);
    await (await inEditorSection(page, page.getByRole('button', { name: 'Odobrať poslednú značku' }))).first().click();
    await expect(svg.locator('[data-mark-id]')).toHaveCount(3);
    await (await inEditorSection(page, page.getByRole('button', { name: 'Pridať krok', exact: false }))).click();
    await (await inEditorSection(page, page.getByLabel('Názov kroku', { exact: true }))).fill('Kontrola štítku');
    await (await inEditorSection(page, page.getByRole('button', { name: 'Krok 2 nahor', exact: true }))).click();
    await expect((await inEditorSection(page, page.locator('.step-select strong'))).first()).toHaveText('Kontrola štítku');
    await (await inEditorSection(page, page.getByRole('button', { name: 'Krok 1 nadol', exact: true }))).click();
    await expect((await inEditorSection(page, page.locator('.step-select strong'))).first()).toHaveText('Kontrola obvodu');
    await expect(page.getByText('Uložené v tomto prehliadači', { exact: true })).toBeVisible();
    await page.reload();
    await (await inEditorSection(page, page.getByRole('button', { name: 'Otvoriť', exact: false }))).click();
    await (await inEditorSection(page, page.locator('.step-select'))).first().click();
    await expect((await inEditorSection(page, page.locator('.photo-card')))).toHaveCount(2);
    await expect((await inEditorSection(page, page.locator('.photo-card svg'))).first().locator('[data-mark-id]')).toHaveCount(3);
    const downloadPromise = page.waitForEvent('download');
    await (await inEditorSection(page, page.getByRole('button', { name: 'Export projektu', exact: false }))).click();
    const download = await downloadPromise;
    await download.saveAs('test-results/project.json');
    await (await inEditorSection(page, page.getByRole('button', { name: 'Náhľad A3', exact: true }))).click();await expect((await inEditorSection(page, page.locator('.preview-area .document-pages')))).toHaveAttribute('data-ready','true');
    await expect((await inEditorSection(page, page.locator('.instruction-table > tbody > tr')))).toHaveCount(2);
    await expect((await inEditorSection(page, page.locator('.paper'))).first()).toContainText('DH110-750');
    await expect((await inEditorSection(page, page.locator('.paper .picture')))).toHaveCount(2);
    await page.screenshot({ path: 'test-results/a3-preview.png', fullPage: true });
    await page.emulateMedia({ media: 'print' });
    await page.pdf({ path: 'test-results/navodka.pdf', format: 'A3', printBackground: true, preferCSSPageSize: true });
    await page.emulateMedia({ media: 'screen' });
    await (await inEditorSection(page, page.getByRole('button', { name: '← Návodky', exact: true }))).click();
    await (await inEditorSection(page, page.locator('input[type=file]'))).first().setInputFiles('test-results/project.json');
    await expect((await inEditorSection(page, page.getByLabel('Číslo produktu / Product number')))).toHaveValue('DH110-750');
    await expect((await inEditorSection(page, page.locator('.photo-card')))).toHaveCount(2);
    await page.screenshot({ path: 'test-results/editor.png', fullPage: true });
    const bundlePromise=page.waitForEvent('download');
    await (await inEditorSection(page, page.getByRole('button',{name:'Uložiť celú návodku (ZIP)',exact:false}))).click();
    const bundle=await bundlePromise;await bundle.saveAs('test-results/project.zip');
    const files=unzipSync(new Uint8Array(readFileSync('test-results/project.zip')));
    files['navodka.csv']=strToU8(strFromU8(files['navodka.csv']).replace('Skontrolovať obvod','Upravené cez CSV: skontrolovať obvod'));
    await (await inEditorSection(page, page.getByRole('button',{name:'← Návodky',exact:true}))).click();
    await (await inEditorSection(page, page.locator('input[type=file]'))).first().setInputFiles({name:'uprava.zip',mimeType:'application/zip',buffer:Buffer.from(zipSync(files))});
    await expect((await inEditorSection(page, page.getByLabel('Popis postupu / kontrolné kritériá')))).toContainText('Upravené cez CSV');
    await expect((await inEditorSection(page, page.locator('.photo-card')))).toHaveCount(2);
    await expect((await inEditorSection(page, page.locator('.photo-card svg'))).first().locator('[data-mark-id]')).toHaveCount(3);
    page.once('dialog', d => d.accept());
    await (await inEditorSection(page, page.getByRole('button', { name: 'Vymazať fotografiu diel-nok.png', exact: true }))).click();
    await expect((await inEditorSection(page, page.locator('.photo-card')))).toHaveCount(1);
    page.once('dialog', d => d.accept());
    await (await inEditorSection(page, page.getByRole('button', { name: 'Vymazať krok 2', exact: true }))).click();
    await expect((await inEditorSection(page, page.locator('.step-select')))).toHaveCount(1);
    await expect(errors).toEqual([]);
});
