test('súbor zo zálohy na inom počítači obnoví fotky a vytvorí novú revíziu',async({page,browser})=>{
 await page.goto('/');
 const src=await page.evaluate(()=>{const c=document.createElement('canvas');c.width=200;c.height=100;const ctx=c.getContext('2d')!;ctx.fillStyle='#50836a';ctx.fillRect(0,0,200,100);return c.toDataURL('image/png')});
 const p={version:1,id:'prenos-projekt',product:'PRENOS',process:'Kontrola zo zálohy',revision:'01',author:'Sabína',date:'2026-11-07',updated:Date.now(),steps:[{id:'prenos-krok',title:'Kontrola dielu',description:'Pôvodný postup',time:25,status:'OK',photos:[{id:'prenos-foto',name:'diel.png',src,status:'OK',marks:[{id:'prenos-znacka',type:'rect',x:10,y:10,ex:60,ey:70,color:'#ff0000',n:1}]}]}]};
 await (await inEditorSection(page, page.locator('input[type=file]'))).first().setInputFiles({name:'projekt.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(p))});
 const wait=page.waitForEvent('download');await (await inEditorSection(page, page.getByRole('button',{name:'Uložiť celú návodku (ZIP)',exact:false}))).click();const dl=await wait;expect(dl.suggestedFilename()).toBe('PRENOS-rev-01.zip');await dl.saveAs('test-results/prenos.zip');
 // Nový kontext simuluje iný počítač bez pôvodnej lokálnej databázy.
 const context=await browser.newContext();const other=await context.newPage();
 try{await other.goto('/');await expect((await inEditorSection(other, other.locator('.project-card')))).toHaveCount(0);
 await (await inEditorSection(other, other.locator('input[type=file]'))).first().setInputFiles('test-results/prenos.zip');
 await expect((await inEditorSection(other, other.getByLabel('Popis postupu / kontrolné kritériá')))).toHaveValue('Pôvodný postup');
 await expect((await inEditorSection(other, other.locator('.photo-card')))).toHaveCount(1);await expect((await inEditorSection(other, other.locator('.photo-card svg rect')))).toHaveCount(1);
 expect(await (await inEditorSection(other, other.locator('.photo-card img'))).evaluate((el:HTMLImageElement)=>el.src)).toBe(src);
 other.once('dialog',d=>d.accept('02'));await (await inEditorSection(other, other.getByRole('button',{name:'＋ Nová revízia',exact:true}))).click();
 await expect((await inEditorSection(other, other.getByLabel('Revízia / Revision',{exact:true})))).toHaveValue('02');await expect((await inEditorSection(other, other.locator('.photo-card svg rect')))).toHaveCount(1);
 await (await inEditorSection(other, other.getByLabel('Popis postupu / kontrolné kritériá'))).fill('Upravený postup revízie 02');
 await (await inEditorSection(other, other.getByRole('button',{name:'← Návodky',exact:true}))).click();
 await (await inEditorSection(other, other.locator('.project-card'))).filter({hasText:'REV. 01'}).getByRole('button',{name:'Otvoriť',exact:false}).click();
 await expect((await inEditorSection(other, other.getByLabel('Popis postupu / kontrolné kritériá')))).toHaveValue('Pôvodný postup');await expect((await inEditorSection(other, other.getByLabel('Popis postupu / kontrolné kritériá')))).toBeDisabled();
 }finally{await context.close()}
});

